86	// RedactedBytes represents transcript data that has been through secret
87	// redaction. Consumers that require pre-redacted input (e.g., compact.Compact,
88	// checkpoint stores) accept this type to enforce the contract at compile time.
89	//
90	// Produced by JSONLBytes (primary constructor) or trusted wrappers for data
91	// previously persisted by checkpoint writers.
92	type RedactedBytes struct {
93		data []byte
94	}
95	
96	// Bytes returns the underlying byte slice.
97	func (r RedactedBytes) Bytes() []byte {
98		return r.data
99	}
100	
101	// Len returns the number of bytes in the redacted payload.
102	func (r RedactedBytes) Len() int {
103		return len(r.data)
104	}
105	
106	// AlreadyRedacted wraps transcript bytes known to already be redacted by a
107	// prior write path. Use this ONLY for trusted sources such as persisted
108	// checkpoint transcripts or controlled test fixtures. For fresh transcript
109	// input, use JSONLBytes.
110	func AlreadyRedacted(data []byte) RedactedBytes {
111		return RedactedBytes{data: data}
112	}
