130	// region represents a byte range to redact.
131	type region struct{ start, end int }
132	
133	// taggedRegion extends region with a label for typed replacement tokens.
134	// Empty label = secret (produces "REDACTED"). Non-empty = PII (produces "[REDACTED_<LABEL>]").
135	type taggedRegion struct {
136		region
137	
138		label string
139	}
140	
141	type jsonReplacement struct {
142		key      string
143		original string
144		redacted string
145	}
