501	// Bytes is a convenience wrapper around String for []byte content.
502	func Bytes(b []byte) []byte {
503		s := string(b)
504		redacted := String(s)
505		if redacted == s {
506			return b
507		}
508		return []byte(redacted)
509	}
510	
511	// JSONLBytes redacts secrets in JSONL-formatted byte content and returns
512	// the result as RedactedBytes, certifying the output has been through redaction.
513	func JSONLBytes(b []byte) (RedactedBytes, error) {
514		s := string(b)
515		redacted, err := JSONLContent(s)
516		if err != nil {
517			return RedactedBytes{}, err
518		}
519		if redacted == s {
520			return RedactedBytes{data: b}, nil
521		}
522		return RedactedBytes{data: []byte(redacted)}, nil
523	}
524	
525	// JSONLBytesWithPrivacyFilter augments JSONLBytes with the OpenAI Privacy
526	// Filter. Use only at condensation/export boundaries; per-turn writes must
527	// use JSONLBytes.
528	func JSONLBytesWithPrivacyFilter(ctx context.Context, b []byte) (RedactedBytes, error) {
529		s := string(b)
530		redacted, err := JSONLContentWithPrivacyFilter(ctx, s)
531		if err != nil {
532			return RedactedBytes{}, err
533		}
534		if redacted == s {
535			return RedactedBytes{data: b}, nil
536		}
537		return RedactedBytes{data: []byte(redacted)}, nil
538	}
539	
540	// BytesWithPrivacyFilter augments Bytes with the OpenAI Privacy Filter for
541	// raw (non-JSONL) byte content. Used by checkpoint write paths that handle
542	// metadata files which may or may not be JSONL.
543	func BytesWithPrivacyFilter(ctx context.Context, b []byte) []byte {
544		s := string(b)
545		redacted := StringWithPrivacyFilter(ctx, s)
546		if redacted == s {
547			return b
548		}
549		return []byte(redacted)
550	}
551	
552	// JSONLContent parses each line as JSON to determine which string values
553	// need redaction, then performs targeted replacements on the raw JSON bytes.
554	// Lines with no secrets are returned unchanged, preserving original formatting.
555	//
556	// For multi-line JSON content (e.g., pretty-printed single JSON objects like
557	// OpenCode export), the function first attempts to parse the entire content as
558	// a single JSON value. This ensures field-aware redaction (which skips ID fields)
559	// is used instead of falling back to entropy-based detection on raw text lines,
560	// which would corrupt high-entropy identifiers.
561	func JSONLContent(content string) (string, error) {
562		return jsonlContentImpl(content, String)
563	}
564	
565	// jsonlContentImpl is the body of JSONLContent parameterized by a per-leaf
566	// redactor. JSONLContent passes String (regex layers only). The OPF-enabled
567	// flow uses two passes: one with a collector that records leaves and returns
568	// identity, one with a redactor that combines regex layers with cached OPF
569	// spans for the recorded leaves.
570	func jsonlContentImpl(content string, redactor func(string) string) (string, error) {
571		// Try parsing the entire content as a single JSON value first.
572		// Uses a streaming decoder to avoid copying the full content into []byte.
573		// After decoding, attempts a second Decode to confirm EOF — if it succeeds,
574		// the content is JSONL (multiple values) and we fall through to line-by-line.
575		trimmed := strings.TrimSpace(content)
576		if len(trimmed) > 0 {
577			dec := json.NewDecoder(strings.NewReader(trimmed))
578			var parsed any
579			if err := dec.Decode(&parsed); err == nil && isSingleJSONValue(dec) {
580				// Content is a single JSON value (object/array) — redact field-aware.
581				result, err := applyJSONReplacements(content, collectJSONLReplacements(parsed, redactor))
582				if err != nil {
583					return "", err
584				}
585				return result, nil
586			}
587		}
588	
589		// Fall back to line-by-line JSONL processing.
590		lines := strings.Split(content, "\n")
591		var b strings.Builder
592		for i, line := range lines {
593			if i > 0 {
594				b.WriteByte('\n')
595			}
596			lineTrimmed := strings.TrimSpace(line)
597			if lineTrimmed == "" {
598				b.WriteString(line)
599				continue
600			}
601			var parsed any
602			if err := json.Unmarshal([]byte(lineTrimmed), &parsed); err != nil {
603				b.WriteString(redactor(line))
604				continue
605			}
606			result, err := applyJSONReplacements(line, collectJSONLReplacements(parsed, redactor))
607			if err != nil {
608				return "", err
609			}
610			b.WriteString(result)
611		}
612		return b.String(), nil
613	}
