700	// applyJSONReplacements applies collected (original, redacted) string pairs
701	// to the raw JSON text, replacing JSON-encoded originals with their redacted forms.
702	// Returns s unchanged if repls is empty.
703	func applyJSONReplacements(s string, repls []jsonReplacement) (string, error) {
704		if len(repls) == 0 {
705			return s, nil
706		}
707		for _, r := range repls {
708			origJSON, err := jsonEncodeString(r.original)
709			if err != nil {
710				return "", err
711			}
712			replJSON, err := jsonEncodeString(r.redacted)
713			if err != nil {
714				return "", err
715			}
716			if r.key == "" {
717				s = strings.ReplaceAll(s, origJSON, replJSON)
718				continue
719			}
720			keyJSON, err := jsonEncodeString(r.key)
721			if err != nil {
722				return "", err
723			}
724			s = replaceKeyedJSONValue(s, keyJSON, origJSON, replJSON)
725		}
726		return s, nil
727	}
728	
729	// replaceKeyedJSONValue replaces every occurrence of origJSON that follows
730	// keyJSON + optional whitespace + ':' + optional whitespace. Restricts
731	// substitution to value positions so a key's own redacted text is not
732	// rewritten when it collides with another field's value.
733	func replaceKeyedJSONValue(s, keyJSON, origJSON, replJSON string) string {
734		if !strings.Contains(s, keyJSON) {
735			return s
736		}
737		var b strings.Builder
738		b.Grow(len(s))
739		i := 0
740		for i < len(s) {
741			j := strings.Index(s[i:], keyJSON)
742			if j < 0 {
743				b.WriteString(s[i:])
744				break
745			}
746			keyEnd := i + j + len(keyJSON)
747			b.WriteString(s[i : i+j])
748			b.WriteString(keyJSON)
749			p := keyEnd
750			for p < len(s) && isJSONWhitespace(s[p]) {
751				p++
752			}
753			if p >= len(s) || s[p] != ':' {
754				i = keyEnd
755				continue
756			}
757			p++
758			for p < len(s) && isJSONWhitespace(s[p]) {
759				p++
760			}
761			if p+len(origJSON) <= len(s) && s[p:p+len(origJSON)] == origJSON {
762				b.WriteString(s[keyEnd:p])
763				b.WriteString(replJSON)
764				i = p + len(origJSON)
765				continue
766			}
767			i = keyEnd
768		}
769		return b.String()
770	}
771	
772	func isJSONWhitespace(c byte) bool {
773		return c == ' ' || c == '\t' || c == '\n' || c == '\r'
774	}
775	
776	// isSingleJSONValue returns true if the decoder has reached EOF (no more
777	// top-level values). This distinguishes a single JSON value (e.g., pretty-printed
778	// object) from JSONL (multiple concatenated values). We attempt a second Decode
779	// and require io.EOF rather than relying on dec.More(), which is documented for
780	// use inside arrays/objects and not for top-level value boundaries.
781	func isSingleJSONValue(dec *json.Decoder) bool {
782		var discard json.RawMessage
783		return dec.Decode(&discard) == io.EOF
784	}
785	
786	// collectJSONLReplacements walks a parsed JSON value and collects unique
787	// string replacements via the supplied per-leaf redactor. JSONLContent
788	// passes String; the OPF-enabled flow passes a closure that combines the
789	// regex layers with cached batched OPF spans.
790	func collectJSONLReplacements(v any, redactor func(string) string) []jsonReplacement {
791		seen := make(map[string]bool)
792		var repls []jsonReplacement
793		var walk func(key string, credentialContext bool, v any)
794		walk = func(key string, credentialContext bool, v any) {
795			switch val := v.(type) {
796			case map[string]any:
797				if shouldSkipJSONLObject(val) {
798					return
799				}
800				childCredentialContext := credentialContext || isCredentialJSONObject(val)
801				for k, child := range val {
802					if shouldSkipJSONLField(k) {
803						continue
804					}
805					walk(k, childCredentialContext, child)
806				}
807			case []any:
808				for _, child := range val {
809					walk("", credentialContext, child)
810				}
811			case string:
812				redacted := redactor(val)
813				if redacted == val && isCredentialJSONSecretKey(key, credentialContext) && hasNonPlaceholderPasswordValue(val) {
814					redacted = RedactedPlaceholder
815				}
816				if redacted != val {
817					seenKey := key + "\x00" + val
818					if !seen[seenKey] {
819						seen[seenKey] = true
820						repls = append(repls, jsonReplacement{key: key, original: val, redacted: redacted})
821					}
822				}
823			}
824		}
825		walk("", false, v)
826		return repls
827	}
828	
829	// shouldSkipJSONLField returns true if a JSON key should be excluded from scanning/redaction.
830	// Skips signature fields (any key ending in "signature"), ID fields (ending in "id"/"ids"),
831	// and common path/directory fields.
832	func shouldSkipJSONLField(key string) bool {
833		lower := strings.ToLower(key)
834	
835		// Skip signature fields: cryptographic attestations, not secrets. Covers
836		// "signature" (Claude Code) and provider variants like "thinkingSignature"
837		// (Oh My Pi). Their values are high-entropy base64, so the entropy scanner
838		// would otherwise redact them — corrupting extended-thinking signatures and
839		// breaking transcript replay ("Invalid `signature` in `thinking` block").
840		if strings.HasSuffix(lower, "signature") {
841			return true
842		}
843	
844		// Skip ID fields
845		if strings.HasSuffix(lower, "id") || strings.HasSuffix(lower, "ids") {
846			return true
847		}
848	
849		// Skip common path and directory fields from agent transcripts.
850		// These appear frequently in tool calls and are structural, not secrets.
851		switch lower {
852		case "filepath", "file_path", "cwd", "root", "directory", "dir", "path":
853			return true
854		}
855	
856		return false
857	}
858	
859	// shouldSkipJSONLObject returns true if the object has "type":"image" or "type":"image_url".
860	func shouldSkipJSONLObject(obj map[string]any) bool {
861		t, ok := obj["type"].(string)
862		return ok && (strings.HasPrefix(t, "image") || t == "base64")
863	}
864	
865	func shannonEntropy(s string) float64 {
866		if len(s) == 0 {
867			return 0
868		}
869		freq := make(map[byte]int)
870		for i := range len(s) {
871			freq[s[i]]++
872		}
873		length := float64(len(s))
874		var entropy float64
875		for _, count := range freq {
876			p := float64(count) / length
877			entropy -= p * math.Log2(p)
878		}
879		return entropy
880	}
881	
882	// jsonEncodeString returns the JSON encoding of s without HTML escaping.
883	func jsonEncodeString(s string) (string, error) {
884		var buf bytes.Buffer
885		enc := json.NewEncoder(&buf)
886		enc.SetEscapeHTML(false)
887		if err := enc.Encode(s); err != nil {
888			return "", fmt.Errorf("json encode string: %w", err)
889		}
890		return strings.TrimSuffix(buf.String(), "\n"), nil
891	}
