// extract pulls full.jsonl blobs out of the repo's checkpoint refs into a
// corpus directory for redaction A/B testing.
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"log"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
)

const repo = "/Users/peytonmontei/Documents/entire/devenv/entireio/cli/.worktrees/support"

func git(args ...string) []byte {
	cmd := exec.Command("git", args...)
	cmd.Dir = repo
	out, err := cmd.Output()
	if err != nil {
		log.Fatalf("git %v: %v", args, err)
	}
	return out
}

func main() {
	corpus := os.Args[1]
	if err := os.MkdirAll(corpus, 0o755); err != nil {
		log.Fatal(err)
	}

	refs := strings.Fields(string(git("for-each-ref", "--format=%(refname)", "refs/entire/checkpoints/")))
	var files, total int
	const maxRefs = 80
	const maxTotal = 60 << 20
	for i, ref := range refs {
		if i >= maxRefs || total >= maxTotal {
			break
		}
		id := filepath.Base(ref)
		sc := bufio.NewScanner(bytes.NewReader(git("ls-tree", "-r", ref)))
		sc.Buffer(make([]byte, 1<<20), 1<<20)
		for sc.Scan() {
			parts := strings.Fields(sc.Text())
			if len(parts) < 4 || !strings.HasSuffix(parts[3], "full.jsonl") {
				continue
			}
			blob := parts[2]
			size, _ := strconv.Atoi(strings.TrimSpace(string(git("cat-file", "-s", blob))))
			if size < 10_000 || size > 8_000_000 {
				continue
			}
			data := git("cat-file", "blob", blob)
			name := fmt.Sprintf("%s_%s.jsonl", id, blob[:8])
			if err := os.WriteFile(filepath.Join(corpus, name), data, 0o644); err != nil {
				log.Fatal(err)
			}
			files++
			total += size
		}
	}
	fmt.Printf("extracted %d files, %d bytes\n", files, total)
}

// redactcorpus runs redact.JSONLBytes over every file in a corpus dir and
// writes redacted output to an output dir. Built twice: once against
// betterleaks 1.5.0 (via replace) and once against 1.8.0.
package main

import (
	"fmt"
	"log"
	"os"
	"path/filepath"

	"github.com/entireio/cli/redact"
)

func main() {
	in, out := os.Args[1], os.Args[2]
	if err := os.MkdirAll(out, 0o755); err != nil {
		log.Fatal(err)
	}
	entries, err := os.ReadDir(in)
	if err != nil {
		log.Fatal(err)
	}
	for _, e := range entries {
		data, err := os.ReadFile(filepath.Join(in, e.Name()))
		if err != nil {
			log.Fatal(err)
		}
		red, err := redact.JSONLBytes(data)
		if err != nil {
			log.Fatalf("%s: %v", e.Name(), err)
		}
		if err := os.WriteFile(filepath.Join(out, e.Name()), red.Bytes(), 0o644); err != nil {
			log.Fatal(err)
		}
	}
	fmt.Printf("redacted %d files into %s\n", len(entries), out)
}

